<script setup>
import {ref,computed,onMounted} from 'vue'
import {api,session} from '../../services/api.js'
import GlassWindow from '../GlassWindow.vue'
const props=defineProps({administration:Boolean})
const canAdmin=computed(()=>['owner','admin'].includes(session.user?.role)),tab=ref('reporters'),result=ref({items:[],total:0,page:1,pages:1}),q=ref(''),applied=ref(''),page=ref(1),sort=ref(''),order=ref('asc'),limit=ref(25),health=ref(null),settings=ref(null),nodes=ref([]),actors=ref([]),error=ref(''),message=ref(''),busy=ref(false),dialog=ref(false),editing=ref(null),form=ref({}),nodeChoice=ref(''),secret=ref(''),secretOpen=ref(false),confirmation=ref(null),confirmOpen=ref(false)
const path=computed(()=>tab.value==='rules'?'service-rules':'reporters'),time=v=>v?new Date(v).toLocaleString():'Never'
async function load(){error.value='';try{[result.value,health.value]=await Promise.all([api(`/ai/${path.value}?${new URLSearchParams({q:applied.value,page:page.value,limit:limit.value,sort:sort.value,order:order.value})}`),api('/ai/health')]);page.value=result.value.page;if(!settings.value)settings.value={...health.value.settings}}catch(e){error.value=e.message}}
function search(){applied.value=q.value;page.value=1;load()}
function switchTab(value){tab.value=value;q.value='';applied.value='';sort.value='';page.value=1;load()}
function sorting(key){order.value=sort.value===key&&order.value==='asc'?'desc':'asc';sort.value=key;page.value=1;load()}
function edit(row){editing.value=row?.id||null;nodeChoice.value='';error.value='';form.value=tab.value==='rules'?{hostname:row?.hostname||'',match:row?.match||'exact',provider:row?.provider||'',service:row?.service||'',role:row?.role||'api',sourceUrl:row?.source_url||'',reviewedAt:row?.reviewed_at||new Date().toISOString().slice(0,10),enabled:row?.enabled??true}:{name:row?.name||'',coverage:row?.coverage||'self-reported',nodeIds:[...(row?.nodeIds||[])],actorId:row?.actor_id||'',issuer:row?.oauthBinding?.issuer||'',subject:row?.oauthBinding?.subject||'',clientId:row?.oauthBinding?.clientId||''};dialog.value=true}
async function save(){busy.value=true;error.value='';try{const body={...form.value};if(tab.value==='reporters'){if(!body.actorId)body.actorId=null;if(!body.issuer){delete body.issuer;delete body.subject;delete body.clientId}}const saved=await api(`/ai/${path.value}${editing.value?'/'+encodeURIComponent(editing.value):''}`,{method:editing.value?'PATCH':'POST',body});dialog.value=false;if(saved.credential){secret.value=saved.credential;secretOpen.value=true}message.value='Saved.';await load()}catch(e){error.value=e.message}finally{busy.value=false}}
function confirm(action,row){confirmation.value={action,row};confirmOpen.value=true}
async function execute(){busy.value=true;try{const {action,row}=confirmation.value,r=await api(row?`/ai/reporters/${encodeURIComponent(row.id)}/${action}`:`/ai/${action}`,{method:'POST'});confirmOpen.value=false;if(r.credential){secret.value=r.credential;secretOpen.value=true}message.value=action==='purge'?'Expired metadata purged in a bounded batch. Scheduled retention continues until the backlog is clear.':action==='backfill'?'Retained-event reclassification queued.':`Reporter ${action==='rotate'?'credential rotated':'revoked'}.`;await load()}catch(e){error.value=e.message}finally{busy.value=false}}
async function saveSettings(){busy.value=true;try{settings.value=await api('/ai/settings',{method:'PATCH',body:settings.value});message.value='AI collection settings saved.';await load()}catch(e){error.value=e.message}finally{busy.value=false}}
function addNode(){if(nodeChoice.value&&!form.value.nodeIds.includes(nodeChoice.value)){if(form.value.coverage!=='collector')form.value.nodeIds=[];form.value.nodeIds.push(nodeChoice.value)}nodeChoice.value=''}
onMounted(async()=>{await load();if(canAdmin.value)try{[nodes.value,actors.value]=await Promise.all([api('/nodes'),api('/users')])}catch(e){error.value=e.message}})
defineExpose({refresh:load})
</script>
<template><div class="ai-section"><p v-if="error" class="error-msg" role="alert">{{error}}</p><p v-if="message" class="success-msg" role="status">{{message}}</p><p class="ai-note">Self-reported coverage depends on the reporter. Instrumented adapters record the operations they observe. A healthy heartbeat does not prove complete coverage. Unbound collectors remain unmapped.</p><div v-if="health" class="ai-summary"><article><span>Reporters</span><strong>{{health.reporters.active}} active</strong><small>{{health.reporters.stale}} stale · {{health.reporters.total}} enrolled</small></article><article><span>Processing queue</span><strong>{{health.backlog}}</strong><small>{{health.worker.dropped}} dropped · {{health.worker.schema_errors}} schema errors</small></article><article><span>DNS coverage</span><strong>{{health.dns.nodes}} nodes</strong><small>Last answer: {{time(health.dns.lastObservation)}}</small></article><article><span>Worker</span><strong>{{health.settings.enabled?'Enabled':'Paused'}}</strong><small>{{health.worker.last_error||time(health.worker.last_success_at)}}</small><small>{{health.backfill.firewallRemaining+health.backfill.browserRemaining}} source rows remain</small></article></div><nav v-if="administration" class="view-tabs" aria-label="AI administration sections"><button v-for="[key,label] in [['reporters','Reporters'],['rules','Service catalog'],['settings','Collection settings']]" :key="key" :class="{active:tab===key}" @click="switchTab(key)">{{label}}</button></nav><template v-if="tab!=='settings'"><section class="panel glass"><div class="panel-title ai-toolbar"><h2>{{tab==='rules'?'AI service catalog':'Reporters / coverage'}}</h2><div class="ai-actions"><button v-if="canAdmin" class="button primary small" @click="edit(null)">{{tab==='rules'?'Add service rule':'Enroll reporter'}}</button><router-link v-if="canAdmin&&!administration" class="button secondary small" to="/admin?tab=aiUsage">Collection settings and catalog</router-link></div></div><form class="ai-filters" @submit.prevent="search"><label>Search<input v-model.trim="q" maxlength="200" placeholder="Name, coverage, status or service"></label><label>Rows<select v-model.number="limit" @change="page=1;load()"><option :value="25">25</option><option :value="50">50</option><option :value="100">100</option></select></label><div class="ai-actions"><button class="button secondary">Search</button><button type="button" class="button secondary" @click="load">Refresh</button></div></form><div class="ai-scroll table-wrap" tabindex="0" aria-label="AI configuration table"><table><thead><tr v-if="tab==='reporters'"><th><button class="ai-sort" @click="sorting('name')">Reporter ↕</button></th><th><button class="ai-sort" @click="sorting('coverage')">Coverage ↕</button></th><th>Authorized nodes</th><th><button class="ai-sort" @click="sorting('status')">Status ↕</button></th><th>Last report / Heartbeat</th><th>Client health</th><th>Actions</th></tr><tr v-else><th><button class="ai-sort" @click="sorting('hostname')">Hostname ↕</button></th><th><button class="ai-sort" @click="sorting('provider')">Provider ↕</button></th><th>Service / Match</th><th><button class="ai-sort" @click="sorting('role')">Role ↕</button></th><th>Provenance / Version</th><th>State</th><th>Actions</th></tr></thead><tbody><tr v-for="r in result.items" :key="r.id"><template v-if="tab==='reporters'"><td>{{r.name}}<small>{{r.id}}</small><small>{{r.oauth?'OAuth + enrollment credential':'Enrollment credential'}}</small></td><td>{{r.coverage}}</td><td>{{r.nodeIds.length?r.nodeIds.map(id=>nodes.find(n=>n.id===id)?.hostname||id).join(', '):'Unmapped'}}</td><td>{{r.status}}<small v-if="r.status==='active'">{{r.stale?'Heartbeat stale / not received':'Heartbeat current'}}</small></td><td>{{time(r.last_report_at)}}<small>{{time(r.last_heartbeat_at)}}</small></td><td>{{r.health.queued||0}} queued · {{r.health.dropped||0}} dropped<small>{{r.health.schemaErrors||0}} schema errors</small><small>{{r.accepted}} accepted · {{r.duplicates}} retries</small></td><td><div v-if="canAdmin" class="ai-actions"><a v-if="r.userApiKeyId" class="ai-link" href="/admin?tab=security&securityTab=api-keys">Manage API key</a><button v-else class="ai-link" @click="edit(r)">Edit bindings</button><button v-if="!r.userApiKeyId" class="ai-link" :disabled="r.status!=='active'" @click="confirm('rotate',r)">Rotate</button><button class="ai-link" :disabled="r.status!=='active'" @click="confirm('revoke',r)">Revoke</button></div><span v-else>Read only</span></td></template><template v-else><td>{{r.hostname}}</td><td>{{r.provider}}</td><td>{{r.service}}<small>{{r.match}}</small></td><td>{{r.role}}</td><td><a :href="r.source_url" target="_blank" rel="noopener noreferrer">Documentation</a><small>{{r.reviewed_at}} · v{{r.version}} · {{r.builtin?'Built-in':'Organization rule'}}</small></td><td>{{r.enabled?'Enabled':'Disabled'}}</td><td><button v-if="canAdmin" class="ai-link" @click="edit(r)">Edit rule</button></td></template></tr><tr v-if="!result.items.length"><td colspan="7">{{tab==='rules'?'No service rules match.':'No reporters match. Enroll a reporter to begin collecting usage.'}}</td></tr></tbody></table></div><div class="ai-pagination"><span>{{result.total}} records</span><div class="ai-actions"><button class="button secondary small" :disabled="page<=1" @click="page--;load()">Previous</button><span>Page {{page}} / {{result.pages}}</span><button class="button secondary small" :disabled="page>=result.pages" @click="page++;load()">Next</button></div></div></section></template><form v-else-if="settings" class="ai-form ai-card" @submit.prevent="saveSettings"><label class="ai-switch ai-full"><button type="button" role="switch" :aria-checked="settings.enabled" aria-label="Enable AI metadata collection" @click="settings.enabled=!settings.enabled"></button>Enable AI metadata collection</label><p class="ai-note ai-full">Metadata only. Prompts, responses, tool arguments and raw URLs are excluded. Disabling collection pauses ingestion and correlation; retention continues.</p><label>Retention (days)<input v-model.number="settings.retentionDays" type="number" min="1" max="3650" required></label><label>Correlation window (seconds)<input v-model.number="settings.correlationWindowSeconds" type="number" min="1" max="600" required></label><label>DNS evidence window (seconds)<input v-model.number="settings.dnsWindowSeconds" type="number" min="1" max="600" required></label><label>Stale heartbeat (minutes)<input v-model.number="settings.staleReporterMinutes" type="number" min="1" max="1440" required></label><div class="ai-full"><h3>Remote MCP authentication</h3><p class="ai-note">{{health?.oauth.configured?'OAuth provider configured':'OAuth is not configured. User MCP keys can be created in Administration → Security → API keys without an OAuth provider.'}}</p><p v-if="health?.oauth.configured" class="ai-note">Issuer: {{health.oauth.issuer}} · Resource: {{health.oauth.audience}}</p></div><div v-if="canAdmin" class="ai-actions ai-full"><button class="button primary" :disabled="busy">Save settings</button><button type="button" class="button secondary" @click="confirm('backfill')">Reclassify retained events</button><button type="button" class="button secondary" @click="confirm('purge')">Purge expired metadata</button></div></form>
<GlassWindow v-model="dialog" :title="tab==='rules'?(editing?'Edit AI service rule':'Add AI service rule'):(editing?'Edit reporter bindings':'Enroll AI reporter')" width="720px"><form class="ai-form" @submit.prevent="save"><template v-if="tab==='rules'"><label>Hostname<input v-model.trim="form.hostname" required maxlength="253" placeholder="ai.example.com"></label><label>Match<select v-model="form.match"><option value="exact">Exact hostname</option><option value="suffix">Domain and subdomains</option></select></label><label>Provider key<input v-model.trim="form.provider" required pattern="[A-Za-z0-9_.:/@-]+" maxlength="128"></label><label>Service name<input v-model.trim="form.service" required maxlength="100"></label><label>Endpoint role<select v-model="form.role"><option v-for="role in ['api','web','auth','update','telemetry','shared']" :key="role">{{role}}</option></select></label><label>Reviewed on<input v-model="form.reviewedAt" type="date" required></label><label class="ai-full">Documentation URL<input v-model.trim="form.sourceUrl" type="url" required placeholder="https://docs.example.com/ai"></label><label class="ai-switch ai-full"><button type="button" role="switch" :aria-checked="form.enabled" aria-label="Enable service rule" @click="form.enabled=!form.enabled"></button>Enabled</label><p class="ai-note ai-full">Rules identify service contact. Authentication, updates, telemetry and shared endpoints are supporting traffic. Changes retain prior rule evidence and reclassify retained events.</p></template><template v-else><label>Reporter name<input v-model.trim="form.name" required maxlength="100"></label><label>Coverage<select v-model="form.coverage"><option value="self-reported">Self-reported</option><option value="instrumented">Instrumented adapter</option><option value="collector">Scoped multi-node collector</option></select></label><label class="ai-full">Authorize a node<select v-model="nodeChoice" @change="addNode"><option value="">Select a node</option><option v-for="node in nodes" :key="node.id" :value="node.id">{{node.hostname}} · {{node.ip}}</option></select></label><div class="ai-actions ai-full"><span v-for="id in form.nodeIds" :key="id" class="status">{{nodes.find(n=>n.id===id)?.hostname||id}} <button type="button" class="ai-link" :aria-label="`Remove binding ${id}`" @click="form.nodeIds=form.nodeIds.filter(n=>n!==id)">Remove</button></span><span v-if="!form.nodeIds.length" class="ai-note">Unmapped: no node is authorized.</span></div><label class="ai-full">Actor (optional administrator binding)<select v-model="form.actorId"><option value="">Unknown actor</option><option v-for="actor in actors" :key="actor.id" :value="actor.id" :disabled="!!actor.suspended">{{actor.email}}{{actor.suspended?' (suspended)':''}}</option></select></label><p class="ai-note ai-full">Only a collector may authorize multiple nodes; its reports must select an authorized node. Do not bind a shared runner to a downstream machine without verified identity.</p><h3 class="ai-full">OAuth binding (remote MCP)</h3><label class="ai-full">Issuer URL<input v-model.trim="form.issuer" type="url" placeholder="https://identity.example.com/realms/winfire"></label><label>Token subject<input v-model.trim="form.subject" :required="!!form.issuer"></label><label>Client ID<input v-model.trim="form.clientId" :required="!!form.issuer"></label><p class="ai-note ai-full">Use the subject and client ID issued by your configured identity provider. Enrollment credentials are for REST and the local stdio adapter.</p></template><p v-if="error" class="error-msg ai-full" role="alert">{{error}}</p><div class="ai-actions ai-full"><button type="button" class="button secondary" @click="dialog=false">Cancel</button><button class="button primary" :disabled="busy">{{busy?'Saving…':'Save'}}</button></div></form></GlassWindow>
<GlassWindow :model-value="secretOpen" title="Copy reporter credential" width="650px" @update:model-value="secretOpen=$event;if(!$event)secret=''"><div class="ai-section"><p>This credential is shown once. Store it in the reporter's environment or credential store.</p><code class="ai-secret">{{secret}}</code><button class="button primary" @click="secretOpen=false;secret=''">Done</button></div></GlassWindow><GlassWindow v-model="confirmOpen" title="Confirm AI administration action" width="540px"><div class="ai-section"><p>{{confirmation?.action==='revoke'?'Revoke this reporter? REST and OAuth ingestion will stop immediately. Existing history remains.':confirmation?.action==='rotate'?'Rotate this reporter credential? The previous enrollment credential stops working immediately. OAuth bindings remain unchanged.':confirmation?.action==='purge'?'Purge metadata older than the configured retention period? Expired records cannot be restored.':'Reclassify retained source events with the current catalog? This runs in bounded background batches.'}}</p><p v-if="error" class="error-msg">{{error}}</p><div class="ai-actions"><button class="button secondary" @click="confirmOpen=false">Cancel</button><button class="button primary" :disabled="busy" @click="execute">Confirm</button></div></div></GlassWindow></div></template>
<style scoped src="./ai.css"></style>
